insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain array methods in your own words.","Recognise and apply: map returns a new array with every item transformed.","Recognise and apply: filter returns a new array with only the items that pass a test.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers array methods: map, filter, reduce, find and forEach for transforming collections. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that map returns a new array with every item transformed. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that filter returns a new array with only the items that pass a test. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how array methods fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const scores = [8, 5, 9, 7];
