insert into public.topics (module_id, slug, title, summary, position, published) select id, 'asynchronous-javascript', 'Asynchronous JavaScript', 'The event loop, callbacks and why code does not always run in written order.', 0, true from public.modules where level_id = 2 and title = 'JavaScript ES6+ & Async' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain asynchronous javascript in your own words.","Recognise and apply: JavaScript is single-threaded; slow work is handed off and resumed later.","Recognise and apply: setTimeout schedules a callback; it does not pause the code after it.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers asynchronous javascript: the event loop, callbacks and why code does not always run in written order. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that JavaScript is single-threaded; slow work is handed off and resumed later. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that setTimeout schedules a callback; it does not pause the code after it. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how asynchronous javascript fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'console.log(''First'');
