insert into public.topics (module_id, slug, title, summary, position, published) select id, 'promises-and-async-await', 'Promises and Async/Await', 'Writing readable async code with promises and await.', 0, true from public.modules where level_id = 2 and title = 'JavaScript ES6+ & Async' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain promises and async/await in your own words.","Recognise and apply: a promise is pending, then fulfilled with a value or rejected with an error.","Recognise and apply: await pauses only the async function until the promise settles.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers promises and async/await: writing readable async code with promises and await. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a promise is pending, then fulfilled with a value or rejected with an error. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that await pauses only the async function until the promise settles. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how promises and async/await fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'async function loadLesson() {
