insert into public.topics (module_id, slug, title, summary, position, published) select id, 'fetch-api', 'Fetch API', 'Requesting data from a server with fetch, handling responses and errors.', 0, true from public.modules where level_id = 2 and title = 'JavaScript ES6+ & Async' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain fetch api in your own words.","Recognise and apply: fetch returns a promise of a Response; check response.ok before reading the body.","Recognise and apply: network failures reject the promise; HTTP errors like 404 do not.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers fetch api: requesting data from a server with fetch, handling responses and errors. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that fetch returns a promise of a Response; check response.ok before reading the body. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that network failures reject the promise; HTTP errors like 404 do not. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how fetch api fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const res = await fetch(''/api/verify-certificate'', { method: ''POST'' });
