insert into public.topics (module_id, slug, title, summary, position, published) select id, 'json-and-api-integration', 'JSON and API Integration', 'JSON as the data format of APIs, parsing, stringifying and shaping responses.', 0, true from public.modules where level_id = 2 and title = 'JavaScript ES6+ & Async' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain json and api integration in your own words.","Recognise and apply: JSON.stringify turns an object into a JSON string; JSON.parse turns it back.","Recognise and apply: never trust API data blindly — validate the fields you use.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers json and api integration: JSON as the data format of APIs, parsing, stringifying and shaping responses. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that JSON.stringify turns an object into a JSON string; JSON.parse turns it back. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that never trust API data blindly — validate the fields you use. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how json and api integration fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'javascript', 'const payload = JSON.stringify({ code: ''NEX-XXXX'', studentId: ''123'' });
