insert into public.topics (module_id, slug, title, summary, position, published) select id, 'git-fundamentals', 'Git Fundamentals', 'Version control basics: repositories, commits, branches and history.', 0, true from public.modules where level_id = 2 and title = 'Git & GitHub' on conflict (slug) do nothing;
insert into public.lessons (topic_id, objectives, explanation, code_lang, code, code_explanation, activity, mistakes, recap, version) select id, '["Explain git fundamentals in your own words.","Recognise and apply: a commit is a snapshot of your work with a clear message.","Recognise and apply: branches let you work on a feature without touching the main line.","Complete the practical activity and check it against the success criteria."]'::jsonb, '["This lesson covers git fundamentals: version control basics: repositories, commits, branches and history. It is written for a complete beginner, so every idea is introduced in plain language before any code appears.","The first key idea is that a commit is a snapshot of your work with a clear message. In practice that means a learner should be able to recognise it in a real page or project, not only repeat a definition. Work through the example below slowly and predict what each line does before reading its explanation.","The second key idea is that branches let you work on a feature without touching the main line. This is the idea most beginners get wrong, so the common-mistakes section below shows the wrong version next to the corrected version.","Finally, remember that how git fundamentals fits into real web development work. A professional developer does not memorise every detail — they understand the idea, practise it on a small real task, and check their work. That is exactly what the practical activity at the end of this lesson asks you to do."]'::jsonb, 'bash', 'git init
